import type {MedusaRequest,MedusaResponse} from '@medusajs/framework/http'
import {ContainerRegistrationKeys} from '@medusajs/framework/utils'
const aid=(r:MedusaRequest)=>(r as any).auth_context?.actor_id||(r as any).auth_context?.auth_identity_id
async function sid(req:MedusaRequest,a:string){const q=req.scope.resolve(ContainerRegistrationKeys.QUERY) as any;try{const {data}=await q.graph({entity:'seller_member',fields:['seller.id','seller.name'],filters:{member_id:a},pagination:{take:1}});return data?.[0]?.seller||null}catch{return null}}
export async function GET(req:MedusaRequest,res:MedusaResponse){const a=aid(req);if(!a)return res.status(401).json({message:'Unauthorized'});const seller=await sid(req,a);if(!seller)return res.status(403).json({message:'Seller not found'});const q=req.scope.resolve(ContainerRegistrationKeys.QUERY) as any;const {data}=await q.graph({entity:'order',fields:['id','display_id','status','created_at','email','currency_code','shipping_address.*','metadata','items.id','items.title','items.product_id','items.variant_id','items.quantity','items.unit_price','items.total','items.offer.seller_id','shipping_methods.id','shipping_methods.amount','shipping_methods.metadata'],pagination:{take:100,order:{created_at:'DESC'}}});const orders=(data||[]).map((o:any)=>{const items=(o.items||[]).filter((i:any)=>i.offer?.seller_id===seller.id);if(!items.length)return null;const subtotal=items.reduce((n:number,i:any)=>n+Number(i.total??(Number(i.unit_price||0)*Number(i.quantity||1))),0);return {...o,items,seller_id:seller.id,seller_name:seller.name,seller_status:o.metadata?.[`spike_seller_status_${seller.id}`]||'under_review',seller_subtotal:subtotal}}).filter(Boolean);res.json({orders})}
